// DATENQUALITÄTS-CHECK VOR TAGESREPORT
// Modus: runOnceForAllItems
// Warnungen nur bei echten Problemen (fehlende Signale, Fundamental-Fehler, leerer Report).
// "Keine News heute" ist ein Hinweis, keine Warnung.

const alleItems = $input.all();
const reportdaten = alleItems[0]?.json || {};

const techSignale   = reportdaten.technische_signale || [];
const fundamentals  = reportdaten.fundamentaldaten   || [];
const nachrichten   = reportdaten.nachrichten        || [];
const kandidaten    = reportdaten.handelskandidaten  || [];
const beobachten    = reportdaten.beobachten_liste   || [];
const heute         = new Date().toISOString().substring(0, 10);

const fundFehler = fundamentals.filter(f =>
  f.status === 'fehler' || String(f.fehler || '').length > 0
).length;

const techFehler = techSignale.filter(s =>
  String(s.fehler || '').length > 0
).length;

const letzterTechZeitstempel = techSignale
  .map(s => s.zeitstempel || '')
  .filter(Boolean)
  .sort()
  .reverse()[0] || 'unbekannt';

const marktKontext = (reportdaten.marktumfeld && reportdaten.marktumfeld.kontext) || [];

const techHeuteCount = techSignale.filter(s => String(s.datum || '').startsWith(heute)).length;
const techStale = techSignale.length > 0 && techHeuteCount === 0;
const techStaleDatum = techStale
  ? (techSignale.map(s => s.datum || '').filter(Boolean).sort().reverse()[0] || 'unbekannt')
  : null;

const marktKontextHeuteCount = marktKontext.filter(m => String(m.datum || '').startsWith(heute)).length;
const marktKontextStale = marktKontext.length > 0 && marktKontextHeuteCount === 0;
const marktKontextStaleDatum = marktKontextStale
  ? (marktKontext.map(m => m.datum || '').filter(Boolean).sort().reverse()[0] || 'unbekannt')
  : null;

const fundamentalHeuteCount = fundamentals.filter(f => String(f.datum || '').startsWith(heute)).length;
const fundamentalStale = fundamentals.length > 0 && fundamentalHeuteCount === 0;
const fundamentalStaleDatum = fundamentalStale
  ? (fundamentals.map(f => f.datum || '').filter(Boolean).sort().reverse()[0] || 'unbekannt')
  : null;

const newsHochMittel = nachrichten.filter(n =>
  n.relevanz === 'hoch' || n.relevanz === 'mittel'
).length;

const reportKompLettLeer =
  techSignale.length === 0 &&
  fundamentals.length === 0 &&
  nachrichten.length === 0;

// Warnungen: nur echte Workflow-Probleme
const warnungen = [
  ...(techSignale.length < 10 && techSignale.length > 0
      ? [`Nur ${techSignale.length} technische Signale (erwartet: 15)`] : []),
  ...(techSignale.length === 0
      ? ['KEINE technischen Signale – Kurs-Strang prüfen'] : []),
  ...(techStale
      ? [`VERALTET: Technische Signale sind nicht von heute (zuletzt: ${techStaleDatum}) – Workflow 02 Technische Signale prüfen`] : []),
  ...(marktKontextStale
      ? [`VERALTET: Marktumfeld ist nicht von heute (zuletzt: ${marktKontextStaleDatum}) – Workflow 02b Marktumfeld prüfen`] : []),
  ...(fundamentalStale
      ? [`VERALTET: Fundamentaldaten sind nicht von heute (zuletzt: ${fundamentalStaleDatum}) – Workflow 01 Fundamentaldaten prüfen`] : []),
  ...(fundFehler > 5
      ? [`${fundFehler} Fundamentaldaten fehlerhaft`] : []),
  ...(reportKompLettLeer
      ? ['KRITISCH: Report hat keine Daten – gesamten Workflow prüfen'] : [])
];

// Hinweise: normale Betriebszustände, kein Alert
const hinweise = [
  ...(nachrichten.length === 0
      ? ['Keine relevanten News heute – normal außerhalb der Handelszeiten'] : []),
  ...(kandidaten.length === 0
      ? ['Heute keine Handelskandidaten – Markt seitwärts oder kein klares Signal'] : [])
];

const datenqualitaet = {
  fundamental_gesamt:          fundamentals.length,
  fundamental_fehler:          fundFehler,
  fundamental_ok:              fundamentals.length - fundFehler,
  fundamental_stale:           fundamentalStale,
  fundamental_stale_datum:     fundamentalStaleDatum,
  tech_signale_gesamt:         techSignale.length,
  tech_signale_fehler:         techFehler,
  tech_signale_ok:             techSignale.length - techFehler,
  tech_signale_stale:          techStale,
  tech_signale_stale_datum:    techStaleDatum,
  tech_kandidaten:             kandidaten.length,
  tech_beobachten:             beobachten.length,
  letzter_tech_zeitstempel:    letzterTechZeitstempel,
  markt_kontext_gesamt:        marktKontext.length,
  markt_kontext_stale:         marktKontextStale,
  markt_kontext_stale_datum:   marktKontextStaleDatum,
  news_gesamt:                 nachrichten.length,
  news_hoch_mittel:            newsHochMittel,
  heute,
  warnungen,
  hinweise
};

return [{ json: { ...reportdaten, datenqualitaet } }];

