const ki = $input.item.json;

function extractReportText(obj) {
  // Neue OpenAI Responses-Struktur in n8n
  if (typeof obj.output_text === 'string' && obj.output_text.trim()) {
    return obj.output_text.trim();
  }

  if (Array.isArray(obj.output)) {
    for (const msg of obj.output) {
      if (Array.isArray(msg.content)) {
        for (const c of msg.content) {
          if (typeof c.text === 'string' && c.text.trim()) {
            return c.text.trim();
          }
        }
      }
    }
  }

  // Alte Chat-Completions-Struktur
  if (typeof obj.text === 'string' && obj.text.trim()) {
    return obj.text.trim();
  }

  if (typeof obj.message?.content === 'string' && obj.message.content.trim()) {
    return obj.message.content.trim();
  }

  if (typeof obj.choices?.[0]?.message?.content === 'string' && obj.choices[0].message.content.trim()) {
    return obj.choices[0].message.content.trim();
  }

  return JSON.stringify(obj, null, 2);
}

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function markdownToSimpleHtml(markdown) {
  let html = escapeHtml(markdown);

  // Überschriften
  html = html.replace(/^### (.*)$/gm, '<h3>$1</h3>');
  html = html.replace(/^## (.*)$/gm, '<h2>$1</h2>');
  html = html.replace(/^# (.*)$/gm, '<h1>$1</h1>');

  // Fett
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

  // Kursiv (erst NACH Fett, damit ** nicht als zwei einzelne * erkannt wird)
  html = html.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');

  // Inline-Code
  html = html.replace(/`([^`\n]+)`/g, '<code>$1</code>');

  // Aufzählungen: nur fuehrende Leerzeichen/Tabs erlauben (kein \s, das wuerde
  // Zeilenumbrueche/Leerzeilen verschlucken und mehrere Listen verschmelzen)
  html = html.replace(/^[ \t]*-\s+(.*)$/gm, '<li>$1</li>');
  // jeden zusammenhaengenden Block aus <li>-Zeilen einzeln in <ul> wrappen,
  // statt alle <li> im Dokument in ein einziges <ul> zu packen
  html = html.replace(/(?:^<li>.*<\/li>$\n?)+/gm, (block) => `<ul>\n${block.trim()}\n</ul>\n`);

  // Absätze / Zeilenumbrüche
  html = html
    .split(/\n{2,}/)
    .map(block => {
      const trimmed = block.trim();
      if (!trimmed) return '';
      if (
        trimmed.startsWith('<h1>') ||
        trimmed.startsWith('<h2>') ||
        trimmed.startsWith('<h3>') ||
        trimmed.startsWith('<ul>')
      ) {
        return trimmed;
      }
      return `<p>${trimmed.replace(/\n/g, '<br>')}</p>`;
    })
    .join('\n');

  return html;
}

function buildEmpfehlungsMarkdown() {
  let ew;
  try {
    ew = $('Report: Datenqualität prüfen').item.json.empfehlungswatchlist;
  } catch (e) {
    ew = null;
  }
  if (!ew) return '';

  let md = '\n\n## 11. Empfehlungs-Watchlist (News + Signal, hypothetisch)\n\n';
  md += `Offene Positionen: ${ew.anzahl_offen} | Geschlossene Positionen: ${ew.anzahl_geschlossen}\n\n`;
  if (ew.durchschnitt_performance_geschlossen !== null) {
    md += `Durchschnittliche Performance geschlossener Positionen: ${ew.durchschnitt_performance_geschlossen}%\n`;
    md += `Trefferquote (positive Positionen): ${ew.trefferquote_geschlossen}%\n\n`;
  }
  if (ew.offen && ew.offen.length > 0) {
    md += '**Offen:**\n';
    for (const p of ew.offen) {
      md += `- ${p.ticker} (${p.richtung}), Entry ${p.entry_kurs} am ${p.entry_datum}, aktuelle Performance: ${p.live_performance_pct ?? 'n/a'}%\n`;
      if (p.onvista_link) {
        md += `  Hebelprodukt-Suche (Hebel 3-4, ${p.richtung === 'kauf' ? 'Long' : 'Short'} filtern): ${p.onvista_link}\n`;
      }
    }
    md += '\n';
  }
  if (ew.geschlossen && ew.geschlossen.length > 0) {
    md += '**Zuletzt geschlossen:**\n';
    for (const p of ew.geschlossen.slice(-5)) {
      md += `- ${p.ticker} (${p.richtung}), ${p.entry_datum} bis ${p.exit_datum}, Performance: ${p.performance_pct ?? 'n/a'}%\n`;
    }
    md += '\n';
  }
  md += 'Hinweis: rein hypothetische Watchlist basierend auf kombinierten News- und Signal-Treffern (automatisch erzeugt). Keine echten Trades, keine Anlageberatung.\n';
  return md;
}

function buildSignalUebersicht() {
  let daten;
  try {
    daten = $('Report: Datenqualität prüfen').item.json;
  } catch (e) {
    return '';
  }
  const signale = daten.technische_signale || [];
  if (signale.length === 0) return '';

  const dq = daten.datenqualitaet || {};
  let md = '## Signal-Übersicht (auf einen Blick)\n\n';
  if (dq.tech_signale_stale) {
    md += `⚠️ Diese Signale sind vom ${dq.tech_signale_stale_datum}, nicht von heute.\n\n`;
  }

  const kandidaten = signale.filter(s => s.handels_status === 'handelskandidat');
  const beobachten = signale.filter(s => s.handels_status === 'beobachten');
  const rest = signale.length - kandidaten.length - beobachten.length;

  function zeile(s) {
    const rsiTxt = s.rsi != null && s.rsi !== '' ? `RSI ${s.rsi} (${s.rsi_signal || 'n/a'})` : 'RSI n/a';
    const macdTxt = s.macd_signal || 'n/a';
    const richtungTxt = s.richtung || 'n/a';
    return `- ${s.handels_status_text || ''} ${s.ticker} (${s.sektor || 'n/a'}): ${rsiTxt} | MACD ${macdTxt} | Richtung: ${richtungTxt}`;
  }

  if (kandidaten.length > 0) {
    md += '**Handelskandidaten:**\n' + kandidaten.map(zeile).join('\n') + '\n\n';
  } else {
    md += '**Handelskandidaten:** keine heute.\n\n';
  }

  if (beobachten.length > 0) {
    md += '**Beobachten:**\n' + beobachten.map(zeile).join('\n') + '\n\n';
  }

  if (rest > 0) {
    md += `_${rest} weitere Aktie(n) ohne auffälliges Signal (nur_info/ignorieren)._\n\n`;
  }

  md += '---\n';
  return md;
}

const report_text = buildSignalUebersicht() + extractReportText(ki) + buildEmpfehlungsMarkdown();

const matrix_text = report_text.length > 15000
  ? report_text.substring(0, 14800) + '\n\n[Bericht gekürzt - vollständige Version per E-Mail]'
  : report_text;

const matrix_html = markdownToSimpleHtml(matrix_text);
const report_html = markdownToSimpleHtml(report_text);

const email_html = `
<html>
<body style="font-family:Arial,sans-serif;max-width:900px;margin:0 auto;padding:24px;color:#222;line-height:1.6">
  <h1 style="color:#1a1a2e;margin-bottom:4px;">📊 Aktien-Tagesreport</h1>
  <p style="color:#666;margin-top:0;">
    ${new Date().toLocaleDateString('de-DE', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    })}
  </p>

  <div style="background:#f8f9fa;padding:22px;border-radius:10px;border:1px solid #e5e5e5;font-size:15px;">
    ${report_html}
  </div>

  <hr style="margin-top:28px;border:none;border-top:1px solid #ddd;">
  <p style="color:#999;font-size:12px;">
    Automatisch generiert. Keine Anlageberatung, nur automatisierte Markt- und Aktienbeobachtung.
  </p>
</body>
</html>`;

return [
  {
    json: {
      report_text,
      matrix_text,
      matrix_html,
      email_html,
      zeitstempel: new Date().toISOString()
    }
  }
];
